def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)
                if bounds[i] + 1 < bounds[i + 1]]

    row_blocks = intervals(h, sep_rows)
    col_blocks = intervals(w, sep_cols)

    tiles = []
    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0]
            tiles.append((ri, ci, r0, r1, c0, c1, cells))

    candidates = [t for t in tiles if t[1] != 0 and t[6]]
    pattern_tile = max(candidates, key=lambda t: len(t[6]))
    pattern = {(dr, dc) for dr, dc, _ in pattern_tile[6]}
    pattern_color = pattern_tile[6][0][2]

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for ri, (r0, r1) in enumerate(row_blocks):
        c0, c1 = col_blocks[0]
        seed_colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                       if grid[r][c] != 0 and grid[r][c] != pattern_color]
        color = seed_colors[0] if seed_colors else pattern_color
        for tr0, tr1 in [row_blocks[ri]]:
            for tc0, tc1 in col_blocks:
                for dr, dc in pattern:
                    if r0 + dr < tr1 and tc0 + dc < tc1:
                        out[r0 + dr][tc0 + dc] = color
    return out
